+                data-testid='device-detail-heading-input'
+                value={name}
+                maxLength={100}
+                onChange={event => setName(event.target.value)}
+                disabled={isSaving}
+                autoFocus
+            />
+            <p>{ _t('Session names may be visible to people you communicate with.') }</p>
+            { error && <p role='alert' data-testid='device-detail-heading-error'>{ error }</p> }
+            <div className='mx_DeviceDetailHeading_actions'>
+                <button type='submit' data-testid='device-detail-heading-save' disabled={isSaving}>
+                    { _t('Save') }
+                </button>
+                { isSaving && <Spinner w={16} h={16} /> }
+                <button type='button' data-testid='device-detail-heading-cancel' onClick={cancel} disabled={isSaving}>
+                    { _t('Cancel') }
+                </button>
+            </div>
+        </form>;
+    }
+
+    return <div className='mx_DeviceDetailHeading_read' data-testid='device-detail-heading-read'>
+        <Heading size='h3'>{ savedName ?? device.display_name ?? device.device_id }</Heading>
+        <AccessibleButton kind='link_inline' onClick={startEditing} data-testid='device-detail-heading-rename'>
+            { _t('Rename') }
+        </AccessibleButton>
+    </div>;
+};
