+import React, { useEffect, useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Spinner from '../../elements/Spinner';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+import { DevicesState } from './useOwnDevices';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: DevicesState['saveDeviceName'];
+}
+
+export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [isEditing, setIsEditing] = useState(false);
+    const [name, setName] = useState('');
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string>();
+    const [savedName, setSavedName] = useState<string>();
+
+    useEffect(() => {
+        setSavedName(undefined);
+    }, [device.device_id, device.display_name]);
+
+    const startEditing = () => {
+        setName(device.display_name ?? '');
+        setError(undefined);
+        setIsEditing(true);
+    };
+
+    const cancel = () => {
+        setError(undefined);
+        setIsEditing(false);
+    };
+
+    const save = async (event: React.FormEvent) => {
+        event.preventDefault();
+        if (isSaving) return;
+        if (name === (device.display_name ?? '')) {
+            setIsEditing(false);
+            return;
+        }
+        setIsSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, name);
+            setSavedName(name);
+            setIsEditing(false);
+        } catch (error) {
+            setError(_t('Failed to set display name.'));
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    if (isEditing) {
+        return <form className='mx_DeviceDetailHeading_edit' data-testid='device-detail-heading-edit' onSubmit={save}>
+            <label htmlFor={`device-name-${device.device_id}`}>{ _t('Session name') }</label>
+            <input
+                id={`device-name-${device.device_id}`}
+                data-testid='device-detail-heading-input'
+                value={name}
+                maxLength={100}
+                onChange={event => setName(event.target.value)}
+                disabled={isSaving}
+                autoFocus
+            />
+            <p>{ _t('Session names may be visible to people you communicate with.') }</p>
+            { error && <p role='alert' data-testid='device-detail-heading-error'>{ error }</p> }
+            <div className='mx_DeviceDetailHeading_actions'>
+                <button type='submit' data-testid='device-detail-heading-save' disabled={isSaving}>
+                    { _t('Save') }
+                </button>
+                { isSaving && <Spinner w={16} h={16} /> }
+                <button type='button' data-testid='device-detail-heading-cancel' onClick={cancel} disabled={isSaving}>
+                    { _t('Cancel') }
+                </button>
+            </div>
+        </form>;
+    }
+
+    return <div className='mx_DeviceDetailHeading_read' data-testid='device-detail-heading-read'>
+        <Heading size='h3'>{ savedName ?? device.display_name ?? device.device_id }</Heading>
+        <AccessibleButton kind='link_inline' onClick={startEditing} data-testid='device-detail-heading-rename'>
+            { _t('Rename') }
+        </AccessibleButton>
+    </div>;
+};
